const now = new Date();
const hour = now.getHours();
const minute = now.getMinutes();
const day = now.getDay();

// IST offset = UTC+5:30
const istHour = (hour + 5) % 24;
const istMinute = (minute + 30) % 60;

return {
  json: {
    timestamp: now.toISOString(),
    istHour,
    istMinute,
    dayOfWeek: day,
    isMorningDigest: istHour === 9 && istMinute < 15,
    isEveningDigest: istHour === 18 && istMinute < 15,
    isWeeklyReport: day === 0 && istHour === 8 && istMinute < 15,
    isHourlyCheck: istMinute < 15,
    runQueueCheck: true,
    runHealthCheck: true
  }
};

const tasks = $('Get Pending Tasks').all();
const errors = $('Get Open Errors').all();
const approvals = $('Get Pending Approvals').all();
const timeData = $('Time Router').first().json;

// Build digest message
let message = `🤖 *Agency OS — Morning Brief*\n`;
message += `📅 ${new Date().toLocaleDateString('en-IN', {weekday: 'long', day: 'numeric', month: 'long'})}\n\n`;

message += `📋 *Task Queue*\n`;
message += `• ${tasks.length} pending tasks\n\n`;

message += `⚠️ *System Health*\n`;
message += `• ${errors.length} open errors\n`;
message += `• ${approvals.length} items awaiting your approval\n\n`;

if (approvals.length > 0) {
  message += `✅ *Needs Your Decision*\n`;
  approvals.slice(0, 3).forEach(a => {
    message += `• ${a.json['Type']}: ${a.json['Item']}\n`;
  });
  message += `\n`;
}

if (errors.length > 0) {
  message += `🔴 *Open Errors*\n`;
  errors.slice(0, 3).forEach(e => {
    message += `• ${e.json['Workflow']}: ${e.json['Error Message']?.substring(0, 50)}...\n`;
  });
  message += `\n`;
}

message += `_Reply to this message for any action needed._`;

return { json: { message, taskCount: tasks.length, errorCount: errors.length, approvalCount: approvals.length } };

// Log execution to Error Log sheet
const timestamp = new Date().toISOString();
const errorCount = $('Get Open Errors').all().length;

if (errorCount === 0) {
  return { json: { status: 'healthy', timestamp, message: 'All systems operational' } };
}

// Return error details for alerting
const errors = $('Get Open Errors').all();
const critical = errors.filter(e => e.json['Severity'] === 'Critical');

return { 
  json: { 
    status: critical.length > 0 ? 'critical' : 'degraded',
    criticalCount: critical.length,
    totalErrors: errorCount,
    timestamp,
    alertNeeded: critical.length > 0
  } 
};

// Weekly report builder
const tasks = $('Get Pending Tasks').all();
const errors = $('Get Open Errors').all();
const approvals = $('Get Pending Approvals').all();

let report = `📊 *Agency OS — Weekly Report*\n`;
report += `Week ending ${new Date().toLocaleDateString('en-IN')}\n\n`;
report += `*Summary*\n`;
report += `• Pending tasks: ${tasks.length}\n`;
report += `• Open errors: ${errors.length}\n`;
report += `• Pending approvals: ${approvals.length}\n\n`;
report += `*Actions Needed This Week*\n`;
report += `• Review and close all open errors\n`;
report += `• Approve pending content\n`;
report += `• Check lead CRM for follow-ups\n\n`;
report += `_Full details in Agency OS Google Sheet._`;

return { json: { report } };
